const form = document.getElementById('booking-form');
const dateInput = document.getElementById('booking-date');
const list = document.getElementById('booking-list');
const empty = document.getElementById('empty-state');
const confirmation = document.getElementById('booking-confirmation');
const count = document.getElementById('booking-count');
const bookings = [];

function localDateString() {
  const now = new Date();
  const offset = now.getTimezoneOffset() * 60000;
  return new Date(now.getTime() - offset).toISOString().split('T')[0];
}
function formatDate(value) {
  return new Date(value + 'T00:00:00').toLocaleDateString(undefined, {weekday:'short', month:'short', day:'numeric', year:'numeric'});
}
function updateCount() {
  const active = bookings.filter(item => !item.cancelled).length;
  count.textContent = `${active} ${active === 1 ? 'appointment' : 'appointments'}`;
}
function render() {
  list.querySelectorAll('[data-testid="booking"]').forEach(node => node.remove());
  empty.hidden = bookings.length > 0;
  bookings.forEach((item, index) => {
    const card = document.createElement('article');
    card.className = 'booking' + (item.cancelled ? ' cancelled' : '');
    card.dataset.testid = 'booking';
    card.dataset.status = item.cancelled ? 'cancelled' : 'active';
    card.innerHTML = `<div><div class="booking-type">${item.type}</div><p class="booking-name" data-testid="booking-name-display"></p><p class="booking-meta">${formatDate(item.date)} · ${item.time} · ${item.email}</p></div>`;
    card.querySelector('[data-testid="booking-name-display"]').textContent = item.name;
    const action = document.createElement('div');
    if (item.cancelled) { action.className = 'cancelled-label'; action.textContent = 'Cancelled'; }
    else { const button = document.createElement('button'); button.className='cancel'; button.type='button'; button.dataset.testid='booking-cancel'; button.textContent='Cancel'; button.addEventListener('click', () => { item.cancelled=true; render(); }); action.appendChild(button); }
    card.appendChild(action); list.appendChild(card);
  });
  updateCount();
}
dateInput.min = localDateString();
form.addEventListener('submit', event => {
  event.preventDefault();
  if (!form.checkValidity()) { form.reportValidity(); return; }
  const data = new FormData(form);
  const date = data.get('date');
  if (date < localDateString()) { dateInput.setCustomValidity('Please choose today or a future date.'); dateInput.reportValidity(); dateInput.setCustomValidity(''); return; }
  bookings.push({name:data.get('name'), email:data.get('email'), date, time:data.get('time'), type:data.get('type'), cancelled:false});
  render();
  confirmation.textContent = `Appointment confirmed for ${data.get('name')} — ${formatDate(date)} at ${data.get('time')}.`;
  confirmation.hidden = false;
  form.reset(); dateInput.min = localDateString();
  window.setTimeout(() => { confirmation.hidden = true; }, 6000);
});

const form = document.getElementById('booking-form');
const dateInput = document.getElementById('booking-date');
const list = document.getElementById('booking-list');
const empty = document.getElementById('empty-state');
const confirmation = document.getElementById('booking-confirmation');
const count = document.getElementById('booking-count');
const bookings = [];

function localDateString() {
  const now = new Date();
  const offset = now.getTimezoneOffset() * 60000;
  return new Date(now.getTime() - offset).toISOString().split('T')[0];
}
function formatDate(value) {
  return new Date(value + 'T00:00:00').toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' });
}
function updateCount() {
  const active = bookings.filter(item => !item.cancelled).length;
  count.textContent = `${active} ${active === 1 ? 'appointment' : 'appointments'}`;
}
function render() {
  list.querySelectorAll('[data-testid="booking"]').forEach(node => node.remove());
  empty.hidden = bookings.length > 0;
  bookings.forEach(item => {
    const card = document.createElement('article');
    card.className = 'booking' + (item.cancelled ? ' cancelled' : '');
    card.dataset.testid = 'booking';
    card.dataset.status = item.cancelled ? 'cancelled' : 'active';
    card.innerHTML = `<div><div class="booking-type">${item.type}</div><p class="booking-name" data-testid="booking-name-display"></p><p class="booking-meta">${formatDate(item.date)} · ${item.time} · ${item.email}</p></div>`;
    card.querySelector('[data-testid="booking-name-display"]').textContent = item.name;
    const action = document.createElement('div');
    if (item.cancelled) {
      action.className = 'cancelled-label';
      action.textContent = 'Cancelled';
